head.script:
scwin.onpageload = function() {
	dlt_exam_code.setJSON([
		{"label":"Apple","code":"01"},
		{"label":"Pear","code":"02"},
		{"label":"Grapes","code":"03"},
		{"label":"Melon","code":"04"},
		{"label":"Peach","code":"05"}
	]);
};

scwin.checkVal1 = function() {
	return (document.getElementById('ccb_samp_itemTable_main') || document.getElementById('mf_ccb_samp_itemTable_main')).getAttribute('role') == 'listbox';
};
scwin.checkVal2 = function() {
	return (document.getElementById('ccb_samp_itemTable_0') || document.getElementById('mf_ccb_samp_itemTable_0')).getAttribute('aria-checked') === null;
};
scwin.checkVal3 = function() {
	return (document.getElementById('ccb_samp_itemTable_0') || document.getElementById('mf_ccb_samp_itemTable_0')).getAttribute('role') == 'option';
};
